def word_counts(documents):
    counts = {}
    for document in documents:
        for word in document.lower().split():
            counts[word] = counts.get(word, 0) + 1
    return counts

# This example counts words in local documents. The dictionary stores a total
# for each word, and the loop visits every document exactly once. Splitting on
# whitespace is useful for demonstration but does not handle all punctuation.
# Real text pipelines should define their normalization and tokenization rules.
# Empty input returns an empty dictionary. Repeated words increment the existing
# total instead of replacing it. Keeping this function deterministic makes its
# output easy to compare between runs and easy to verify using a small fixture.
